    const l = Array.isArray(ids) ? [...new Set(ids.map(String))] : null;
    if (l && (!l.length || l.length > 200 || !l.every((x) => /^harvest_\d{1,20}_orders_(sold|purchased)$/.test(x)))) return undefined;
    const qui = AUTH.user.id;
