// Indicateur de synchro (mis a jour par l'app)
let _syncListeners = [];
const onSyncChange = (fn) => { _syncListeners.push(fn); return () => { _syncListeners = _syncListeners.filter(f=>f!==fn); }; };
// (16 oct., Julien : « pourquoi le nuage en haut est barré ? ») L'état de la
