    if (m.num) { const tn = v.tn * 0.8, txt = texteEcrivable(bold, m.num), l2 = bold.widthOfTextAtSize(txt, tn); if (l2 > v.l - 2 * P) return null; h += tn * 0.85; lignes.push({ texte: txt, font: bold, taille: tn, y: h }); h += tn * 0.25; w = Math.max(w, l2); }
