// ⟦→ ecrans/Comptabilite.jsx #178⟧
const composerBordereaux = async (items, resolvePos, opts = {}) => {
  const PL = await import('pdf-lib');
  const { PDFDocument } = PL;
  const modeLot = imprMode(opts.imprimante || imprimanteChoisie());
  // (14 nov., lot colis-plus 98) 4 PAR PAGE A4 : la MÊME isolation que la thermique (les mêmes PDF, le
  // même tampon, la page entière quand on ne sait pas), posée dans un document à part, puis rangée
  // quatre par feuille dans l'ordre (`imposerPlanche`). Les factures restent des pages entières.
  const planche = modeLot === 'planche4';
  const thermique = modeLot === 'thermique' || planche;
  const out = await PDFDocument.create();
  let count = 0, nInv = 0, isoles = 0, nEtiquettes = 0, fiches = 0, bandes = 0;
  const entiers = [];   // ce qu'on n'a PAS su isoler — l'écran doit le dire
  const details = [];   // (11 nov., lot thermique) ce qui a été mesuré, étiquette par étiquette
  const reussis = [], rates = [], plages = [];
  // (4 nov., Julien : « pareil pour le tamponnage, on doit pouvoir le faire quand tous les bordereaux
  // sont sélectionnés ») `opts.apercu` : true ⇒ la feuille s'ouvre UNE fois par forme sans place gardée ;
  // 'force' (« Placer le tampon ») ⇒ une fois par forme, toujours ; false ⇒ jamais. Annuler ⇒ rien.
  const dejaLot = {};
  for (const [index, it] of items.entries()) {
    const debut = out.getPageCount();
    try {
      const src = await PDFDocument.load(it.pdfBuf);
      const { width, height } = src.getPages()[0].getSize();
      const pos = resolvePos ? resolvePos(width, height) : null;
      // IMPRIMANTE THERMIQUE : l'étiquette seule, sur des pages 100×150. Si on
      // ne SAIT pas où elle est, la page part ENTIÈRE — jamais un code-barres
      // coupé au hasard (`poserBordereau`, la même règle partout).
      // La position mémorisée de la forme de CE bordereau (`positionTampon`), sinon le choix automatique.
      // (14 nov., Julien : « modifier un par un chaque bordereau avec le tamponnage ») le tampon choisi pour CE
      // bordereau dans l'aperçu (`it.tampon` : N° seul, N° + titre, + taille, rien) remplace le réglage, pour lui seul.
      const impIt = extrasImpression(it.numero, it.title, { photo: it.photo || (it.ligne && it.ligne.photo) || null });
      // (16 nov., lot impression-retours) Un bordereau de RETOUR : le tampon RETOUR, toujours (jamais « N° seul » ni « Rien »).
      if (it.retour) { impIt.retour = true; impIt.emplacement = ''; }   // la paire part : aucune case de rangement
      else if (it.tampon && TAMPONS_IMPR.includes(it.tampon)) impIt.tampon = it.tampon;
      impIt.site = it.site || '';
      if (it.places) impIt.places = it.places;   // (16 nov.) les places posées dans l'aperçu avant impression
      const r1 = await poserBordereau(PL, out, src, { numero: it.numero, title: it.title, pos, thermique, impression: impIt, choisir: it.retour ? null : it.tampon === 'rien' ? null : choisirTampon({ PL, src, numero: it.numero, titre: it.title, apercu: opts.apercu === undefined ? false : opts.apercu, deja: dejaLot, thermique, site: it.site || '' }) });
      for (const t of r1.tampons || []) { if (t === 'fiche') fiches++; else if (t === 'bande') bandes++; }
      details.push(...(r1.details || []));
      if (r1.isole) { isoles++; nEtiquettes += r1.etiquettes; }
      else if (thermique) entiers.push({ titre: it.title || '', raison: r1.raison });
      count++; reussis.push(index);
      // Facture pro juste APRÈS son bordereau (comptes pro uniquement, §41).
      if (it.invBytes) {
        try { const isrc = await PDFDocument.load(it.invBytes); (await out.copyPages(isrc, isrc.getPageIndices())).forEach(p => out.addPage(p)); nInv++; } catch (_) {}
      }
      plages.push({ index, cle: it.cle != null ? String(it.cle) : String(index), debut, n: out.getPageCount() - debut, poses: r1.poses || [], famille: r1.famille || '', ...(it.retour ? { retour: true } : {}) });
    } catch (e) {
      if (estTamponAnnule(e)) throw e;
      // Un bordereau qui casse en route ne laisse aucune page à moitié posée dans le lot.
      try { while (out.getPageCount() > debut) out.removePage(out.getPageCount() - 1); } catch (_) {}
      rates.push(index);
    }
  }
  if (!count) throw new Error('Aucun bordereau exploitable.');
  let docFinal = out, infoPlanche = null, unitBytes = null;
  if (planche) {
    unitBytes = await out.save();
    const { imposerPlanche } = await import('./impression/planche4.js');
    const { doc, plan } = await imposerPlanche(PL, out);
    docFinal = doc;
    infoPlanche = { feuilles: doc.getPageCount(), etiquettes: plan.etiquettes, entieres: plan.entieres, echelle: Math.round(plan.echelle * 100) };
  }
  posePrefsImpression(PL, docFinal);   // une feuille par bordereau (§ recto-verso)
  const bytes = await docFinal.save();
  const filename = `bordereaux-${count}${nInv?'-'+nInv+'factures':''}${planche?'-4-par-page':thermique?'-thermique':''}-a-la-suite.pdf`;
  const base = { bytes, unitBytes: unitBytes || bytes, plages, filename, count, nInv, isoles, etiquettes: nEtiquettes, reussis, rates, fiches, bandes, mode: modeLot };
  if (planche) return { ...base, thermique: false, planche: infoPlanche, entiers: [] };
  return { ...base, thermique, entiers, ...bilanThermique(details) };
};
