const KNOWN_BRANDS=['New Balance','Under Armour','Air Jordan','Le Coq Sportif','Sergio Tacchini',
  'Nike','Adidas','Asics','Jordan','Puma','Reebok','Vans','Converse','Lacoste','Wilson',
  'Babolat','Head','Yonex','Salomon','Brooks','Hoka','Mizuno','Fila','Saucony','New Era',
  'Kappa','Hummel','Umbro','Ellesse','Diadora','Lotto'];
function extractBrand(text){
  if(!text) return null;
  const t=text.toLowerCase();
  for(const b of KNOWN_BRANDS){if(t.includes(b.toLowerCase())) return b;}
  return null;
}
// Extrait une pointure (taille chaussure) depuis un titre d'annonce. Heuristique
// volontairement prudente : "taille 42", "T42", "pointure 40", ou un nombre isolé
// dans la plage 34–52 (les modèles Nike 90/95/97/270… sont hors plage → ignorés).
// Demi-pointures gérées (42,5). Sert uniquement aux stats de sourcing (approximatif).
function extractSize(text){
  if(!text) return null;
  const t=String(text).toLowerCase().replace(',','.');
  const grab=(m)=> m ? m[1]+(/\.5/.test(m[0])?'.5':'') : null;
  let m=t.match(/(?:taille|pointure|t|eu|fr)\s*\.?\s*(3[4-9]|4[0-9]|5[0-2])(?:\.5)?/);
  if(m) return grab(m);
  m=t.match(/(?:^|[^0-9.])(3[4-9]|4[0-9]|5[0-2])(?:\.5)?(?:[^0-9]|$)/);
  return grab(m);
}
// ── LE MODÈLE (pas seulement la marque) ──────────────────────────────────────
// ⚠️ Mesuré sur les vraies données : « même marque + même taille » suffisait à
// remonter UN SEUL candidat pour 5 annonces… dont **2 faux** (un « nike p-6000
// taille 40 » relié à des « Nike speakers maat 40 », un « zoom fly 5 taille 47 »
// relié à une « Air Max 1 taille 47 »). « nike » + « 40 » désigne des centaines
// de paires : ça ne suffit pas à trancher, et un mauvais prix d'achat fausse le
// bénéfice en silence — c'est pire que pas de prix du tout.
// Avec le modèle exigé, les rapprochements uniques deviennent **4 sur 4 justes**.
// ⚠️ LA COULEUR DISTINGUE DEUX PAIRES DU MÊME MODÈLE ET DE LA MÊME TAILLE.
// Mesuré sur les 24 annonces en ligne : « adidas spezial NOIR taille 38 » se
// voyait proposer « Adidas Spezial BLU n. 38 » avec un score de 14 (marque +
// taille + modèle) et le badge « suggéré » — un prix d'achat faux, et un faux
// prix d'achat ne se voit jamais : il produit une marge crédible, pour toujours.
// Julien met systématiquement la couleur dans ses titres, des deux côtés.
// Les variantes couvrent le français, l'anglais, l'italien, l'espagnol,
// l'allemand et le néerlandais : ses achats viennent de toute l'Europe.
const COULEURS = {
  noir:   ['noir','noire','black','nero','negro','schwarz','zwart'],
  blanc:  ['blanc','blanche','white','bianco','blanco','weiss','wit'],
  gris:   ['gris','grise','grey','gray','grigio','grau','grijs'],
  bleu:   ['bleu','bleue','blue','blu','azul','blau','blauw','marine','navy'],
  vert:   ['vert','verte','green','verde','grun','grün','groen','mineral green'],
  rouge:  ['rouge','red','rosso','rojo','rot','rood'],
  rose:   ['rose','pink','rosa','roze'],
  jaune:  ['jaune','yellow','giallo','amarillo','gelb','geel'],
  orange: ['orange','arancione','naranja','oranje'],
  violet: ['violet','purple','viola','morado','lila','paars'],
  beige:  ['beige','sable','sand','crema','creme','crème','cream'],
  marron: ['marron','brown','marrone','braun','bruin'],
};
// Renvoie la couleur reconnue dans un titre, ou null si aucune / plusieurs
// (deux couleurs = bicolore, on ne se prononce pas plutôt que de trancher).
// TOUTES les couleurs reconnues dans un libellé (« noir et violet » → 2).
// ⚠️ Indispensable pour les paires BICOLORES : `extractColor` ne rend qu'une
// couleur ou rien, donc un titre à deux couleurs désactivait complètement le
// test de couleur du sélecteur d'achat — bonus ET pénalité. Mesuré le 23 août
// sur les 212 paires : « Nike zoom fly 5 NOIR VIOLET 41 » se voyait proposer
// « Nike zoom fly 5 maat 41 ORANJE » avec la pastille « suggéré » (score 14,
// pile au seuil), et « Adidas Spezial NOIR ET VERT 38 » recevait
// « Adidas Spezial BLU n. 38 ». Un prix d'achat faux ne se voit jamais.
function extractColors(text){
  if(!text) return [];
  const t = String(text).toLowerCase().replace(/[^a-zà-ÿ0-9]+/g,' ');
  const vues = new Set();
  for(const [nom, mots] of Object.entries(COULEURS))
    for(const m of mots) if(new RegExp('(^| )'+m+'( |$)').test(t)) { vues.add(nom); break; }
  return [...vues];
}
function extractColor(text){
  const v = extractColors(text);
  return v.length === 1 ? v[0] : null;
}

// ── PERTINENCE D'UN ACHAT POUR UNE PAIRE — UNE SEULE DÉFINITION ──────────────
// ⚠️ Ce score vivait DANS `openPicker`, donc à l'intérieur d'un composant : la
// modale de saisie en série ne pouvait pas s'en servir, et le banc devait en
// RECOPIER les poids (donc deux barèmes qui finissent par diverger — c'est très
// exactement ce que §11 interdit). Il est ici, au niveau module, et les deux
// écrans + le banc lisent la même chose.
//
// Le barème est le résultat de trois corrections successives, toutes mesurées :
//   marque +4 · taille identique +4 / DIFFÉRENTE −10 (le signal le plus
//   discriminant, il ne pénalisait rien) · modèle identique +5 / différent −6
//   (c'est lui qui écartait « Nike speakers » d'un p-6000) · une couleur
//   commune +4 / aucune couleur commune −8, sur des ENSEMBLES (une paire
//   bicolore neutralisait tout le test) · payé moins cher que revendu +1 ·
