const SEUIL_SUGGERE = 12;   // en dessous, l'app ne se prononce pas TOUTE SEULE
// ⚠️ MAIS ELLE MONTRE QUAND MÊME LES PISTES, à confirmer À LA MAIN. Mesuré sur
// sa vraie base : le seuil sûr (>=12) couvre 111 paires sur 320 ; au-dessus de
// ce plancher (>=6 : marque + un autre vrai signal), 236 paires ont au moins une
// piste. Les 125 de plus passaient d'un BLANC (saisie aveugle) à un choix
// rapide. On ne relie JAMAIS tout seul sous 12 (§5, un faux prix d'achat ne se
// voit jamais) — la piste porte titre + prix + photo, et c'est LUI qui tape
// dessus. En dessous de 6, c'est du bruit (marque seule = des centaines de
// paires) : on se tait.
const SEUIL_CANDIDAT = 6;
// ⟦→ ecrans/Comptabilite.jsx #182⟧
const KNOWN_MODELS = [
  'zoom fly','p-6000','p6000','p 6000','air max 95','air max 97','air max 1','air max 90','air max',
  'air force','pegasus','vaporfly','alphafly','dunk','blazer','cortez',
  'spezial','samba','gazelle','campus','handball','superstar','stan smith','forum','sl 72',
  'gel-resolution','gel resolution','gel-nimbus','gel nimbus','gel-kayano','gel kayano','gel-lyte','gel lyte',
  'fuelcell','xt-6','xt 6','speedcross','medalist','mexico 66','california','old skool','chuck',
];
function extractModel(text){
  if(!text) return null;
  const t=String(text).toLowerCase().replace(/[^a-z0-9]+/g,' ').replace(/\s+/g,' ').trim();
  // On rend le PLUS LONG modèle reconnu : « air max 95 » doit gagner sur « air max ».
  let best=null;
  for(const m of KNOWN_MODELS){ const k=m.replace(/[^a-z0-9]+/g,' ').trim();
    if(contientModele(t,k) && (!best || k.length>best.length)) best=k; }
  return best;
}
// (30 oct., revue) Un modèle qui finit par un chiffre ne se lit que si AUCUN
// chiffre ne le suit : « air max 1 » n'est pas dans « air max 180 » ni dans
// « air max 1000 » (une autre paire, un autre prix) — avant, une sous-chaîne
// suffisait et l'Air Max 180 recevait le repère de l'Air Max 1, côté ventes
// comme côté eBay. Mieux vaut un blanc qu'un faux.
function contientModele(t,k){
  if(!/\d$/.test(k)) return t.includes(k);
  let i=t.indexOf(k);
  while(i>=0){ if(!/\d/.test(t.charAt(i+k.length))) return true; i=t.indexOf(k,i+1); }
  return false;
}
const COUNTRY_MAP_DATA=[
  [['france'],'France'],[['allemagne','deutschland','germany'],'Allemagne'],
  [['belgique','belgium','belgie'],'Belgique'],[['espagne','españa','spain','espana'],'Espagne'],
  [['italie','italia','italy'],'Italie'],[['pays-bas','nederland','netherlands','holland'],'Pays-Bas'],
  [['suisse','schweiz','switzerland'],'Suisse'],[['luxembourg'],'Luxembourg'],
  [['autriche','österreich','austria','osterreich'],'Autriche'],[['portugal'],'Portugal'],
  [['pologne','poland','polska'],'Pologne'],[['roumanie','romania'],'Roumanie'],
  [['suede','sweden','sverige'],'Suède'],[['danemark','denmark','danmark'],'Danemark'],
  [['tchequie','czech','tschechien'],'Tchéquie'],
];
function extractCountry(address){
  if(!address) return 'France';
  const lines=address.split(/[\n,]+/).map(l=>l.trim().toLowerCase()).filter(Boolean);
  for(const line of [...lines].reverse()){
    for(const [keys,name] of COUNTRY_MAP_DATA){
      if(keys.some(k=>line.includes(k))) return name;
    }
  }
  return 'France';
}
