// ── Notifications ──────────────────────────────────────
// Demande la permission d'envoyer des notifications (à appeler sur action utilisateur).
function askNotifPermission(){
  if(typeof Notification==='undefined') return Promise.resolve('unsupported');
  if(Notification.permission==='granted') return Promise.resolve('granted');
  return Notification.requestPermission().catch(()=>'denied');
}
// Envoie une notification navigateur si autorisée (app ouverte / en arrière-plan récent).
// (5 nov.) `vers` : l'adresse `?tab=…` qu'ouvre un toucher — le MÊME chemin que les
// notifications du serveur (`vrm:aller` → `goto`, qui lit aussi la cible). Sans elle,
// toucher l'alerte ne menait nulle part.
function pushNotif(title, body, vers){
  try{
    if(typeof Notification!=='undefined' && Notification.permission==='granted'){
      // (5 nov.) En mode stream, la notification affichée suit la même règle que l'écran.
      const n=new Notification(textePourStream(title), { body: textePourStream(body), icon:'/vrm-icon-v5-192.png', badge:'/vrm-icon-v5-192.png' });
      if(vers) n.onclick=()=>{ try{ window.focus(); }catch(_){} try{ window.dispatchEvent(new CustomEvent('vrm:aller',{detail:vers})); }catch(_){} try{ n.close(); }catch(_){} };
      return true;
    }
  }catch(_){/* ignore */}
  return false;
}
// (8 nov., Julien : « des infos qui servent à rien ») Une alerte LOCALE ne double
// jamais une notification du serveur (api/_lib/push.js) : l'app au premier plan
// montre déjà le bandeau ; un appareil abonné aux notifications de VRM reçoit la
// vente par le serveur — et « pas su » (abonnement illisible) ne sonne pas non
// plus. Reste : l'app ouverte en arrière-plan sur un appareil NON abonné.
async function alerteLocale(title, body, vers){
  try{
    if(typeof document!=='undefined' && document.visibilityState==='visible') return false;
    if(typeof navigator!=='undefined' && navigator.serviceWorker){
      const reg=await Promise.race([navigator.serviceWorker.ready, new Promise(r=>setTimeout(()=>r(null),1500))]);
      const sub=reg&&reg.pushManager ? await reg.pushManager.getSubscription().catch(()=>undefined) : undefined;
      if(sub!==null) return false;
    }
  }catch(_){ return false; }
  return pushNotif(title, body, vers);
}
