// ── DÉFILEMENT PARTOUT (K1, 30 septembre) ────────────────────────────────────
// Plainte de Julien : « je ne peux pas descendre sur mon ordi, je suis obligé
// d'utiliser la barre glissante, mon pavé tactile ne marche pas ». MESURÉ : dans
// la coque, c'est `<main>` qui défile, pas le document. Une molette / un pavé
// tactile envoie l'événement à ce qui est SOUS le curseur — dans la marge entre
// le rail et la colonne, dans la bande de droite ou sur le rail, aucun ancêtre
// ne défile : 0 px, alors que la barre glissante de `<main>` marche.
// ⇒ Un événement que personne ne peut absorber est renvoyé à `<main>`.
// ⚠️ On ne vole RIEN : un conteneur défilable sous le curseur (fiche, liste,
// modale) garde la main ; au-dessus d'une MODALE plein écran on ne fait
// défiler rien derrière ; Ctrl+molette (zoom) passe tel quel.
function DefilementPartout() {
  React.useEffect(() => {
    const peutDefiler = (el, dy, dx) => {
      const s = getComputedStyle(el);
      if (Math.abs(dy) >= Math.abs(dx)) return /(auto|scroll)/.test(s.overflowY) && el.scrollHeight > el.clientHeight + 1;
      return /(auto|scroll)/.test(s.overflowX) && el.scrollWidth > el.clientWidth + 1;
    };
    const onWheel = (e) => {
      if (e.defaultPrevented || e.ctrlKey) return;
      const main = document.querySelector('main[data-defile]');
      if (!main) return;
      for (let el = e.target; el && el !== document.body && el !== document.documentElement; el = el.parentElement) {
        if (el === main) return;                       // le navigateur s'en charge
        if (peutDefiler(el, e.deltaY, e.deltaX)) return; // un autre conteneur défile
        if (getComputedStyle(el).position === 'fixed') {
          const r = el.getBoundingClientRect();
          if (r.width >= window.innerWidth - 2 && r.height >= window.innerHeight - 2) return; // modale
        }
      }
      if (Math.abs(e.deltaY) < Math.abs(e.deltaX)) return;
      const f = e.deltaMode === 1 ? 16 : e.deltaMode === 2 ? main.clientHeight : 1;
      main.scrollBy({ top: e.deltaY * f });
    };
    window.addEventListener('wheel', onWheel, { passive: true });
    return () => window.removeEventListener('wheel', onWheel);
  }, []);
  return null;
}

function Toaster() {
  const [list, setList] = React.useState([]);
  React.useEffect(() => onToasts(setList), []);
  React.useEffect(() => {
    // pointerdown fonctionne aussi sur un bouton natif désactivé : aucun clic
    // ni faux lien, l'action reste réellement bloquée.
    const expliquer = e => {
      if (e.pointerType !== 'touch' && e.pointerType !== 'pen') return;
      const b = e.target instanceof Element ? e.target.closest('button:disabled,[aria-disabled="true"]') : null;
      if (!b) return;
      const raison = b.getAttribute('title') || b.getAttribute('aria-description') || (b.getAttribute('aria-busy') === 'true' ? 'Cette action est en cours. Attends son résultat avant de réessayer.' : '');
      if (raison) toast(raison, 'info');
    };
    document.addEventListener('pointerdown', expliquer, true);
    return () => document.removeEventListener('pointerdown', expliquer, true);
  }, []);
  // (23 oct.) AU-DESSUS de toute feuille, et EN HAUT de l'écran quand une feuille
  // est ouverte. À 210 sous la coque, un message dit depuis une feuille (« Échec
  // de la suppression — réessaie », « Ces bordereaux n'ont plus leur PDF… »)
  // passait SOUS elle : rien n'était dit. Et en bas il couvrirait le pied de la
  // feuille (« Annuler / Supprimer »). Banc `feuilles-coque.cjs`.
  const enHaut = React.useSyncExternalStore(abonnerFeuilles, uneFeuilleOuverte);
  // (9 nov., DA4) La zone `aria-live` reste montée même vide (une zone créée en même
  // temps que son texte n'est pas annoncée par VoiceOver) ; le message passe au-dessus
  // du CLAVIER (`--vrm-clavier`, lu de `visualViewport` : dit pendant une saisie, il
  // tombait derrière) ; survol, focus clavier, onglet caché : son temps s'arrête.
  const raisons = React.useRef({ survol: false, focus: false, cache: false });
  const suspendre = () => { const r = raisons.current; suspendreToasts(r.survol || r.focus || r.cache); };
  React.useEffect(() => {
    const vis = () => { raisons.current.cache = document.visibilityState === 'hidden'; suspendre(); };
    document.addEventListener('visibilitychange', vis);
    const vv = window.visualViewport;
    const clavier = () => {
      if (!vv) return;
      const h = Math.max(0, Math.round(window.innerHeight - vv.height - vv.offsetTop));
      document.documentElement.style.setProperty('--vrm-clavier', (h > 80 ? h : 0) + 'px');
    };
    if (vv) { vv.addEventListener('resize', clavier); vv.addEventListener('scroll', clavier); clavier(); }
    return () => {
      document.removeEventListener('visibilitychange', vis);
      if (vv) { vv.removeEventListener('resize', clavier); vv.removeEventListener('scroll', clavier); }
    };
  }, []);
  React.useEffect(() => { if (!list.length) { raisons.current.survol = false; raisons.current.focus = false; suspendre(); } }, [list.length]);
  // (19 nov., fiche directe) Une fiche ouverte pose sa zone (src/natif/zoneMessages.js) : la pile s'y range DANS le flux, en
  // haut de la fiche — elle la pousse, elle ne la couvre jamais. Une feuille ouverte par-dessus garde la place d'avant (en haut).
  const zoneFiche = useZoneMessages();
  const dansFiche = !!zoneFiche;   // (la fiche elle-même compte comme une feuille ouverte : `enHaut` y est toujours vrai)
  const pile = (
    <div className="vrm-toasts" data-toasts-place={dansFiche ? 'fiche' : enHaut ? 'haut' : 'bas'} role="status" aria-live="polite" aria-atomic="false" style={{...(dansFiche ? {position:'relative'} : {position:'fixed',left:0,right:0,...(enHaut ? {top:'calc(12px + env(safe-area-inset-top))'} : {bottom:'max(calc(92px + env(safe-area-inset-bottom)), calc(var(--vrm-clavier, 0px) + 12px))'}),zIndex:Z_MESSAGES}),
      display:'flex',flexDirection:'column',alignItems:'center',gap:8,padding:dansFiche ? 0 : '0 14px',pointerEvents:'none'}}
      onPointerEnter={(e) => { if (e.pointerType === 'mouse') { raisons.current.survol = true; suspendre(); } }}
      onPointerLeave={(e) => { if (e.pointerType === 'mouse') { raisons.current.survol = false; suspendre(); } }}
      onFocus={() => { raisons.current.focus = true; suspendre(); }}
      onBlur={(e) => { if (!e.currentTarget.contains(e.relatedTarget)) { raisons.current.focus = false; suspendre(); } }}>
      {list.map(t => {
        const col = t.type==='err' ? C.danger : t.type==='ok' ? INV_STATUS.online.color : C.text;
        return (
          <button className="vrm-toast" data-tone={t.type} key={t.id} type="button" title="Fermer ce message" onClick={()=>dismissToast(t.id)}
            style={{pointerEvents:'auto',maxWidth:520,width:'100%',textAlign:'left',cursor:'pointer',fontFamily:'inherit',
              display:'flex',alignItems:'flex-start',gap:9,padding:'11px 14px',borderRadius:12,
              background:C.card,border:`1px solid ${t.type==='info'?C.border:col+'66'}`,
              boxShadow:C.shadowLg||'0 8px 24px rgba(0,0,0,.2)',
              animation:'cancaleToast .26s cubic-bezier(.32,.72,0,1) both'}}>
            <span className="vrm-toast-icon" aria-hidden="true" style={{color:col}}><Icon name={t.type==='err'?'alert':t.type==='ok'?'check':'info'} size={18}/></span>
            <span style={{fontSize:13,fontWeight:400,color:C.text,lineHeight:1.45,whiteSpace:'pre-wrap'}}>{t.text}</span>
          </button>
        );
      })}
      {/* (14 nov., lot accompagnement) Les gestes courts : résultat et suite, ou échec et geste. */}
      <AccHote/>
    </div>
  );
  return dansFiche ? createPortal(pile, zoneFiche) : pile;
}
