// (19 nov., « VRM natif ») Le menu ☰ « Tous les écrans » (`MenuEcrans`), le rail `SideBar` et la photo de l'en-tête
// (`BoutonProfilTete`) sont retirés : « Plus » (FeuillePlus) et la barre latérale native les remplacent (git log pour l'ancien).

// Retrouver sa position après un passage dans un autre écran.
function MemoireDefilement({ ecran }) {
  const positions=React.useRef(new Map());
  React.useLayoutEffect(()=>{
    const main=document.querySelector('.vrm-main');
    if(!main) return;
    // (5 nov., reprise) La position est rangée sur l'APPAREIL (src/repriseEcran.js) :
    // l'app installée qu'iOS ferme puis rouvre retrouve aussi son défilement.
    const owner=AUTH.user?.id||'';const st=stockageParcours();let gardee=0;try{if(st)gardee=Number(lireParcours(st,owner,'position:'+ecran,0))||0;}catch(_){}
    // (17 nov., chasse-bugs — Julien : « quand j'ai déclaré, ça me met en plein milieu de la page ») La position gardée
    // ne vaut que pour la REPRISE (premier écran après l'ouverture) et le RETOUR par la barre/la colonne ; toute autre
    // arrivée (un geste, une carte, un segment, un retour arrière) ouvre EN HAUT — src/defilementNavigation.js.
    const memorisee=positions.current.get(owner+':'+ecran)??Math.max(0,Math.min(1000000,gardee));
    const cible=positionAOuvrir({ premier: !MemoireDefilement.dejaRendu, retourOnglet: prendreRetourOnglet(), memorisee });
    // La même zone gardait le défilement de l'écran d'avant : remise à 0 — sauf si l'écran qui s'ouvre a DÉJÀ fait défiler
    // lui-même (un lien « aller à cet élément » : la position n'est plus celle laissée en partant).
    // (19 nov., vite-et-sans-bug) LA POSITION SE SUIT, ELLE NE SE RELIT PAS EN PARTANT. Mesuré (trace Chrome, 390 ×4) : le
    // nettoyage de cet effet lisait `main.scrollTop` au MILIEU du rendu validé du changement d'onglet (React nettoie les
    // effets de mise en page pendant ses mutations) — l'écran qui part était encore dans la page et le document venait
    // d'être invalidé en entier (`:has` sur html/body/la coque) : la lecture forçait le recalcul de style de TOUT, écran
    // quitté compris (13 186 éléments en quittant Achats, ~6 000 en quittant Annonces : 0,8 à 2,3 s au ×4), pour un écran
    // retiré juste après. `haut` = la dernière position connue (lue ici une fois, puis à chaque défilement) : le départ,
    // un toucher et le minuteur la reprennent sans rien forcer. Même règle, mêmes valeurs (banc defilement-navigation).
    let haut=main.scrollTop;
    if(cible===0 && haut!==0 && (MemoireDefilement.sortie==null || Math.abs(haut-MemoireDefilement.sortie)<2)){ main.scrollTop=0; haut=0; }
    let position=cible, restauration=cible>0, arrete=false;   // rien à tenir à 0
    // On ne s'arrête pas au premier succès : l'écran peut se raccourcir le temps
    // d'un chargement (le navigateur ramène alors la position à 0). On tient la
    // position 2,5 s, sauf si la personne fait défiler elle-même.
    const restaurer=()=>{ if(!arrete&&restauration&&Math.abs(main.scrollTop-cible)>=2){ main.scrollTop=cible; haut=main.scrollTop; } };
    const lire=()=>{ haut=main.scrollTop; if(!restauration) position=haut; };
    const garderPosition=()=>{try{if(st&&(AUTH.user?.id||'')===owner)garderParcours(st,owner,'position:'+ecran,restauration?cible:haut);}catch(_){}};
    // iOS ne promet pas `pagehide` quand on chasse l'app installée : on range
    // aussi quand elle passe en arrière-plan (le dernier moment sûr).
    const auMasquage=()=>{ if(document.visibilityState==='hidden') garderPosition(); };
    window.addEventListener('pagehide',garderPosition);
    document.addEventListener('visibilitychange',auMasquage);
    const intervenir=()=>{ restauration=false; position=haut; };
    main.addEventListener('scroll',lire,{passive:true});
    main.addEventListener('wheel',intervenir,{passive:true});
    main.addEventListener('touchstart',intervenir,{passive:true});
    window.addEventListener('keydown',intervenir);
    main.addEventListener('pointerdown',intervenir,{passive:true});
    // (18 oct.) On réessaie à chaque image tant que le contenu arrive : la zone
    // porte plusieurs enfants (un bandeau de 74 px en tête), observer le premier
    // ne voyait jamais l'écran grandir, et la position retombait à 0.
    let image=0;
    const boucle=()=>{ restaurer(); if(!arrete&&restauration) image=requestAnimationFrame(boucle); };
    boucle();
    // Au premier écran après une ouverture, les données arrivent du nuage : on
    // tient la position plus longtemps (6 s), sauf geste de la personne.
    const tenir=MemoireDefilement.dejaRendu?2500:6000; MemoireDefilement.dejaRendu=true;
    // (21 nov., fluidité — banc couches-chargement : Annonces revenue en haut, 700 px → 0) Au téléphone (CPU ×4), le premier
    // rendu d'un écran remonté peut prendre plus que ce temps : la position n'était pas encore atteignable (écran trop court)
    // quand on cessait de la tenir. Tant qu'elle n'est pas atteinte, on la tient encore (par pas de 0,5 s, 8 s au plus).
    const debutTenue=Date.now();
    const finirTenue=()=>{ if(!arrete&&restauration&&Math.abs(main.scrollTop-cible)>=2&&Date.now()-debutTenue<8000){ delai=setTimeout(finirTenue,500); return; } restauration=false;position=haut;cancelAnimationFrame(image); };
    let delai=setTimeout(finirTenue,tenir);
    return ()=>{
      arrete=true;clearTimeout(delai);cancelAnimationFrame(image);window.removeEventListener('pagehide',garderPosition);document.removeEventListener('visibilitychange',auMasquage);
      positions.current.set(owner+':'+ecran,position);
      MemoireDefilement.sortie=haut;
      try{if(st&&(AUTH.user?.id||'')===owner)garderParcours(st,owner,'position:'+ecran,position);}catch(_){}
      main.removeEventListener('scroll',lire);main.removeEventListener('wheel',intervenir);main.removeEventListener('touchstart',intervenir);window.removeEventListener('keydown',intervenir);main.removeEventListener('pointerdown',intervenir);
    };
  },[ecran]);
  return null;
}

// (5 nov.) Toucher l'onglet où l'on est déjà ramène en haut de l'écran (le
// geste d'iOS), sans rien changer d'autre. Mouvement réduit ⇒ sans animation.
function remonterEnHaut() {
  try {
    const m = document.querySelector('.vrm-main'); if (!m) return;
    const doux = !(window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches);
    m.scrollTo({ top: 0, behavior: doux ? 'smooth' : 'auto' });
  } catch (_) {}
}
// ⚠️⚠️ LA BARRE DU BAS, REVUE (5 nov., Julien : « ça ne marche pas, c'est pas
// ouf », « revue TOTALEMENT »). Mesuré à 390 px tactile (banc
// scripts/bancs/iphone-reprise.cjs, récit : docs/passation/2026-11-05-iphone-
// reprise.md) : le geste « retour » avec « Plus » ouvert QUITTAIT VRM ; la
// feuille « Plus » couvrait 651 px et la barre (Paramètres hors de l'écran sur
// un iPhone SE) ; sur Statistiques la barre disait seulement « Plus » ; un
// balayage parti du bord gauche (le « retour » d'iOS) changeait AUSSI
// d'onglet ; Ventes et Colis portaient le même nombre côte à côte. Désormais :
// quatre tâches + une 5ᵉ place qui dit où l'on est ; « Plus » = un panneau de
// tuiles AU-DESSUS de la barre ; retour = fermer ; toucher l'onglet courant =
// remonter en haut ; un nombre une seule fois.
// (14 nov., choix n° 61) LE SÉLECTEUR DE « PAIRES » (téléphone) : Annonces | Stock | Achats, en tête des trois
// écrans. Il ne fait que changer d'onglet (les écrans restent tels quels) ; chaque segment porte le nombre de
// son écran (l'onglet « Paires » se tait alors : un nombre une seule fois). Stock suit la règle du menu
// (`groupesVisibles` : en affichage Simple, sans meuble, il ne prend pas de place — sauf s'il est ouvert).
// `data-nav-entree` : le même repère que la barre d'hier (bancs, cibles de notification).
function SelecteurPaires({ tab, setTab, badges, sites }) {
  useProfilVendeur();
  const g = groupesVisibles(sites, () => true).find((x) => x.cle === 'paires');
  const vus = new Set(g ? g.items.map((t) => t.id) : ECRANS_PAIRES);
  vus.add(tab);
  const options = ENTREES_PAIRES.filter((t) => estPaires(t.id) && vus.has(t.id)).map((t) => {
    const v = badges && badges[t.id];
    // (14 nov., intégration) Le nombre du segment porte le même repère que la pastille de la barre d'hier
    // (`data-badge-nav` + `data-badge-n`) : « À retirer · N » se lit au même endroit qu'avant (bancs, cibles).
    const nb = typeof v === 'number' && v > 0;
    return { v: t.id, l: t.label, n: nb ? (v > 99 ? '99+' : v) : undefined, data: { 'data-nav-entree': t.id, 'data-paires-segment': t.id, ...(nb ? { 'data-badge-nav': t.id, 'data-badge-n': String(v) } : {}) } };
  });
  // (16 nov., barre-achats) Achats a son onglet : un sélecteur à un seul segment (Stock caché) ne dit rien.
  if (options.length < 2) return null;
  return <div className="vrm-paires-selecteur" data-paires-selecteur="">
    <Segmente label={tr('nav.paires')} options={options} value={tab} plein onChange={(id) => { if (id === tab) { remonterEnHaut(); return; } noterNavigationSimple(id); setTab(id); }}/>
  </div>;
}
