    T('Montant payé :',W-M-140,y,{s:9,c:gray}); T(eur,W-M-6,y,{s:9,c:gray,right:true}); y-=18;
    T(ent.tvaMention||'TVA non applicable, art. 293 B du CGI',W-M-6,y,{s:9,c:gray,right:true}); y-=24;
