  const ligne = { display: 'flex', gap: 8, alignItems: 'flex-start', fontSize: 13, color: C.text, marginTop: 10, lineHeight: 1.45, cursor: 'pointer' };
  const boite = { marginTop: 2, width: 16, height: 16, flex: '0 0 auto' };
