        if(parcoursNouveauAOuvrir({ pret:true, exemple:exempleActif(), proprietaire:proprio, premierJour:true, valeur:load(CLE_PARCOURS_NOUVEAU,null), bienvenueVue:false })) return;
        setBienvenue(true);
