          const lbcRow=(dvE.aRetirerEbayAilleurs||[]).some(d=>d&&d.ou==='Leboncoin')?await fetch(`${SUPABASE_URL}/rest/v1/app_data?id=eq.lbc_ventes&select=cap:data->>updatedAt`,{headers:sbAuth()}).then(r=>r.ok?r.json():null,()=>null):null;
