          lectures.set(String(a.vinted_user_id),{ lu:l.lu, complet:l.complet===true, enLigne:ids(l.items), masquees:ids(l.masquees), aConfirmer:ids(l.aConfirmer), venduesDressing:new Set((l.soldIds||[]).map(String)) });
